use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-pack-locality176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn save(n:&str,v:&Value){fs::write(r(n),serde_json::to_vec_pretty(v).unwrap()).unwrap();}fn pin(pins:&mut BTreeMap<String,String>,p:impl AsRef<Path>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn link(){assert!(!r("link-plan.json").exists());assert_eq!(read(r("native/result.json"))["status"],"complete");let tests=read(r("native/observer-tests/tests.json"));assert_eq!(tests["passed_tests"].as_array().unwrap().len(),2);let info=read(r("frozen-candidate.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("build-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}for(p,h)in info["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}let dep=Path::new(info["libraries"]["zopro_core"].as_str().unwrap()).parent().unwrap();let sha=fs::read_dir(dep).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("libsha2-")&&p.extension().unwrap()=="rlib").collect::<Vec<_>>();assert_eq!(sha.len(),1);let mut libraries=info["libraries"].as_object().unwrap().clone();libraries.insert("sha2".into(),json!(sha[0]));let mut argv=vec!["/home/ubuntu/.rustup/toolchains/1.98.1-x86_64-unknown-linux-gnu/bin/rustc".to_string(),"--edition=2021".into(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",dep.display())];for(n,p)in libraries{argv.extend(["--extern".into(),format!("{n}={}",p.as_str().unwrap())]);}argv.extend([r("driver.rs").display().to_string(),"-o".into(),r("driver").display().to_string()]);for n in["campaign.rs","campaign","frozen-candidate.json","native/result.json"]{pin(&mut pins,r(n));}save("link-pins.json",&json!(pins));save("link-plan.json",&json!({"version":1,"source_pins":r("link-pins.json"),"steps":[{"kind":"command","name":"link-driver","argv":argv,"environment":{},"timeout_seconds":600}]}));println!("Prepared one explicit optimized diagnostic link; two focused observer tests passed");}
fn prepare(){assert!(!r("capture-plan.json").exists());assert_eq!(read(r("link-runs/result.json"))["status"],"complete");let c=read(r("link-runs/link-driver/command.json"));for x in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(c["argv"].as_array().unwrap().contains(&json!(x)));}let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("link-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}for n in["driver","link-runs/result.json","link-runs/link-driver/command.json"]{pin(&mut pins,r(n));}let fixtures=read("/home/ubuntu/src/zopro-perf-work/late-m3-query176/fixtures.json");let mut steps=Vec::new();let mut jobs=Vec::new();fs::create_dir(r("private")).unwrap();
for shape in["1x2","2x2"]{let fixture=&fixtures[format!("{shape}-B")];let oracle=read(fixture["oracle"].as_str().unwrap());assert_eq!(hash(fixture["fixture"].as_str().unwrap()),oracle["fixture_sha256"]);for k in["fixture","oracle"]{pin(&mut pins,fixture[k].as_str().unwrap());}for workers in[1usize,32]{let name=format!("{shape}-w{workers}");let trace=r(format!("private/{name}.json"));let mut env=read(r("native-plan.json"))["steps"][0]["environment"].clone();for k in["RUSTFLAGS","CARGO_TARGET_DIR","CARGO_BUILD_JOBS","RUSTC","RUSTUP_TOOLCHAIN"]{env.as_object_mut().unwrap().remove(k);}steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c",if workers==1{"2"}else{"0-31"},r("driver"),fixture["fixture"],fixture["oracle"],workers.to_string(),trace],"environment":env,"timeout_seconds":600}));jobs.push(json!({"name":name,"shape":shape,"workers":workers,"fixture":fixture,"private_trace":trace}));}}
save("jobs.json",&json!(jobs));pin(&mut pins,r("jobs.json"));save("capture-pins.json",&json!(pins));save("capture-plan.json",&json!({"version":1,"source_pins":r("capture-pins.json"),"steps":steps}));println!("Prepared four one-query diagnostic processes; no primes/clocks/PMU/proofs; private source ordinals not for publication");}
fn finish(){assert!(!r("analysis.json").exists());assert_eq!(read(r("runs/result.json"))["status"],"complete");for(p,h)in read(r("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut cases=BTreeMap::new();let mut traces=BTreeMap::new();for job in read(r("jobs.json")).as_array().unwrap(){let name=job["name"].as_str().unwrap();let text=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let lines=text.lines().filter_map(|s|s.strip_prefix("LOCALITY ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let v:Value=serde_json::from_str(lines[0]).unwrap();assert_eq!(v["workers"],job["workers"]);assert_eq!(v["point_inputs_unchanged"],true);assert_eq!(v["independent_complete_MSM_hash_matches"],true);assert_eq!(v["no_latency_measurement"],true);assert_eq!(v["new_proofs"],0);assert_eq!(v["root_scopes"],22);let path=job["private_trace"].as_str().unwrap();assert_eq!(hash(path),v["private_transcript_sha256"]);let raw=read(path);assert_eq!(raw["fixture_sha256"],v["fixture_sha256"]);traces.insert(name.to_string(),json!({"path":path,"sha256":hash(path),"bytes":fs::metadata(path).unwrap().len(),"private_input_dependent_ordinals":true}));cases.insert(name.to_string(),v);}
for shape in["1x2","2x2"]{let a=&cases[&format!("{shape}-w1")];let b=&cases[&format!("{shape}-w32")];assert_eq!(a["rows"],b["rows"]);assert_eq!(a["private_transcript_sha256"],b["private_transcript_sha256"]);assert_eq!(a["result_sha256"],b["result_sha256"]);}
let mut totals=BTreeMap::new();for(name,v)in&cases{let mut total=BTreeMap::<String,u64>::new();let mut hist=[0u64;9];for row in v["rows"].as_array().unwrap(){for comp in row["components"].as_array().unwrap(){for k in["batches","pairs","full_groups","scalar_tail_pairs","aligned_consecutive","unaligned_consecutive","single_block_permutation","general_gather","consecutive_edges","possible_edges","unique_source_ordinals"]{*total.entry(k.into()).or_default()+=comp[k].as_u64().unwrap();}for(i,n)in comp["distinct_source_blocks_histogram"].as_array().unwrap().iter().enumerate(){hist[i]+=n.as_u64().unwrap();}}}let groups=total["full_groups"];assert_eq!(total["pairs"],8*groups+total["scalar_tail_pairs"]);let frac=|k:&str|total[k]as f64/groups as f64;totals.insert(name.clone(),json!({"counts":total,"aligned_direct_group_fraction":frac("aligned_consecutive"),"all_consecutive_group_fraction":frac("aligned_consecutive")+frac("unaligned_consecutive"),"single_block_group_fraction":frac("aligned_consecutive")+frac("single_block_permutation"),"general_gather_group_fraction":frac("general_gather"),"distinct_source_blocks_histogram":hist}));}
save("analysis.json",&json!({"complete":true,"diagnostic_only":true,"source_ordinals_identical_across_worker_counts":true,"cases":cases,"totals":totals,"private_transcripts":traces,"new_proofs":0,"proof_ledger":29953,"new_native_key_format":false,"latency_measured":false,"adopted":false,"production_changed":false,"goal_achieved":false}));println!("Finished four complete-MSM locality diagnostics; exact cross-worker ordinal identity; totals{}",serde_json::to_string(&totals).unwrap());}
fn main(){match std::env::args().nth(1).unwrap().as_str(){"link"=>link(),"prepare"=>prepare(),"finish"=>finish(),_=>panic!()}}
